// 1️⃣ Get raw AI text
const rawText =$input.first().json.output || "";

// 2️⃣ Extract SQL inside ```sql ``` block
let sql = "";
const sqlBlockMatch = rawText.match(/```sql([\s\S]*?)```/i);

if (sqlBlockMatch) {
  sql = sqlBlockMatch[1].trim();
} else {
  // Fallback: extract lines that look like SQL
  sql = rawText
    .split("\n")
    .filter(line =>
      /^(CREATE|GRANT)\s+/i.test(line.trim())
    )
    .join("\n")
    .trim();
}

// 3️⃣ Remove trailing explanations accidentally included
sql = sql.replace(/```/g, "").trim();

if (!sql) {
  throw new Error("❌ No SQL detected in AI output");
}

// 4️⃣ Split into individual statements
const statements = sql
  .split(";")
  .map(s => s.trim())
  .filter(Boolean);

// 5️⃣ Whitelist allowed Snowflake statements
const allowedPatterns = [
  /^CREATE\s+OR\s+REPLACE\s+USER\s+USR_[A-Za-z0-9_]+$/i,
  /^GRANT\s+ROLE\s+SYSADMIN\s+TO\s+USER\s+USR_[A-Za-z0-9_]+$/i,
  /^CREATE\s+OR\s+REPLACE\s+USER\s+SVC_[A-Za-z0-9_]+\s+TYPE\s*=\s*'SERVICE'$/i,
  /^GRANT\s+ROLE\s+SYSADMIN\s+TO\s+USER\s+SVC_[A-Za-z0-9_]+$/i,
  /^CREATE\s+OR\s+REPLACE\s+USER\s+SVC_[A-Za-z0-9_]+\s+TYPE\s*=\s*['‘]SERVICE['’]$/i


];

// 6️⃣ Validate statements
const validated = [];

for (const stmt of statements) {
  const allowed = allowedPatterns.some(p => p.test(stmt));
  if (!allowed) {
    throw new Error(`❌ Blocked unsafe SQL: "${stmt}"`);
  }
  validated.push(stmt + ";");
}

// 7️⃣ Output for Snowflake node
return validated.map(stmt => ({
  json: {
    statement: stmt
  }
}));
